<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
const props=defineProps<{prompts:any[];grade_levels:any[];can_manage:boolean}>();const editing=ref<number|null>(null);const blank=()=>({title:'',prompt:'',include_hints:[''],category:'',minimum_grade_level_id:null as number|null,maximum_grade_level_id:null as number|null,active:true});const form=useForm(blank());
const addHint=()=>form.include_hints.push('');const removeHint=(index:number)=>{if(form.include_hints.length>1)form.include_hints.splice(index,1)};const edit=(prompt:any)=>{editing.value=prompt.id;form.title=prompt.title;form.prompt=prompt.prompt;form.include_hints=[...prompt.include_hints];form.category=prompt.category||'';form.minimum_grade_level_id=prompt.minimum_grade_level_id;form.maximum_grade_level_id=prompt.maximum_grade_level_id;form.active=prompt.active;};const cancel=()=>{editing.value=null;form.defaults(blank());form.reset();form.clearErrors();};const save=()=>{const options={preserveScroll:true,onSuccess:cancel};editing.value?form.put(route('creative-writing.prompts.update',editing.value),options):form.post(route('creative-writing.prompts.store'),options);};
</script>
<template><Head title="Creative Writing Prompt Library"/><AuthenticatedLayout><header class="d-flex justify-content-between gap-3 flex-wrap"><div><p class="text-uppercase small fw-bold text-secondary mb-1">Creative Writing Journal</p><h1>Prompt Library</h1><p class="text-secondary">Students see only the prompt assigned to their instructional date.</p></div><Link class="btn btn-outline-secondary align-self-start" :href="route('creative-writing.index')">Journal History</Link></header><form v-if="can_manage" class="card mt-4" @submit.prevent="save"><div class="card-body"><h2 class="h5">{{ editing?'Edit prompt':'Add a prompt' }}</h2><div class="row g-3"><label class="col-md-5">Title<input v-model="form.title" class="form-control"></label><label class="col-md-4">Category<input v-model="form.category" class="form-control"></label><label class="col-md-3 d-flex align-items-end gap-2 pb-2"><input v-model="form.active" type="checkbox"> Active for assignment</label><label class="col-12">Full prompt<textarea v-model="form.prompt" class="form-control" rows="3"/></label><div class="col-12"><strong>Include hints</strong><div v-for="(hint,index) in form.include_hints" :key="index" class="input-group mt-2"><input v-model="form.include_hints[index]" class="form-control"><button class="btn btn-outline-danger" type="button" @click="removeHint(index)">Remove</button></div><button class="btn btn-sm btn-outline-secondary mt-2" type="button" @click="addHint">Add hint</button></div><label class="col-md-6">Minimum grade<select v-model="form.minimum_grade_level_id" class="form-select"><option :value="null">Any</option><option v-for="grade in grade_levels" :key="grade.id" :value="grade.id">{{ grade.name }}</option></select></label><label class="col-md-6">Maximum grade<select v-model="form.maximum_grade_level_id" class="form-select"><option :value="null">Any</option><option v-for="grade in grade_levels" :key="grade.id" :value="grade.id">{{ grade.name }}</option></select></label></div><div v-if="Object.keys(form.errors).length" class="alert alert-danger mt-3" role="alert"><p v-for="(error,key) in form.errors" :key="key" class="mb-1">{{ error }}</p></div><div class="d-flex gap-2 mt-3"><button class="btn btn-primary" :disabled="form.processing">{{ editing?'Save changes':'Add prompt' }}</button><button v-if="editing" class="btn btn-outline-secondary" type="button" @click="cancel">Cancel</button></div></div></form><section class="prompt-list mt-4"><article v-for="prompt in prompts" :key="prompt.id" class="card"><div class="card-body"><div class="d-flex justify-content-between gap-2"><div><span class="badge" :class="prompt.active?'text-bg-success':'text-bg-secondary'">{{ prompt.active?'Active':'Inactive' }}</span><span class="badge text-bg-light border ms-2">{{ prompt.source_type.replace('_',' ') }}</span></div><span class="small text-secondary">{{ prompt.grade_range }}</span></div><h2 class="h5 mt-3">{{ prompt.title }}</h2><p>{{ prompt.prompt }}</p><p class="small mb-1"><strong>Include:</strong> {{ prompt.include_hints.join(' · ') }}</p><p v-if="prompt.category" class="small text-secondary">{{ prompt.category }}</p><div v-if="can_manage" class="d-flex gap-2"><button class="btn btn-sm btn-outline-primary" type="button" @click="edit(prompt)">Edit</button><Link class="btn btn-sm btn-outline-secondary" as="button" method="patch" :href="route('creative-writing.prompts.toggle',prompt.id)">{{ prompt.active?'Deactivate':'Activate' }}</Link></div></div></article></section></AuthenticatedLayout></template>
<style scoped>.prompt-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:1rem}label{font-weight:700}label input,label textarea,label select{margin-top:.35rem;font-weight:400}</style>
